// Status visuals are derived from live gameplay state and source snapshots, not timers of their own.
import {COLORS} from './engine.js';
export const STATUS_LABELS={smith:'Damage boost',well:'Attack speed boost',burn:'Burning',napalm:'Napalm mark',roots:'Entangling roots',corrosion:'Armor corrosion',muck:'Muck slow',nova:'Frost slow',storm:'Storm slow',polar:'Polar mark',voodoo:'Damage vulnerability',enchant:'Armor break',stun:'Stunned',magic:'Magic amplification',fast:'Speed burst',shield:'Mechanical shield',revive:'Undead revival',image:'Minion illusion',healing:'Healing',clone:'Conjured clone',zealot:'Zealot frenzy',quark:'Charged attack',tidal:'Stored Douse'};
const DURATIONS={smith:2,well:2,burn:5,roots:5,corrosion:5,muck:5,nova:5,storm:1.2,polar:15,voodoo:5,enchant:15,stun:1.2,magic:3,fast:1,shield:3,revive:3,image:5,healing:.7};
const STATUS_ELEMENT={well:'water',smith:'fire',burn:'fire',napalm:'fire',roots:'nature',polar:'water',nova:'water',storm:'light',voodoo:'darkness',enchant:'light',stun:'water',clone:'light'};
const FALLBACK={smith:['fire','earth'],well:['water','nature'],burn:['fire'],napalm:['fire','earth','darkness'],roots:['nature','earth','darkness'],corrosion:['fire','nature','darkness'],muck:['earth','water','darkness'],nova:['fire','light','water'],storm:['fire','light','water'],polar:['light','water','earth'],voodoo:['nature','darkness','water'],enchant:['light','nature','earth'],stun:['water','earth'],magic:['darkness'],clone:['light','darkness']};
export function activeStatuses(unit,defs){if(unit.dead)return [];const entries=new Map();const add=(key,data={},fallback)=>{const def=defs[data.sourceType]||fallback,elements=data.sourceElements?.length?data.sourceElements:def?.elements?.length?def.elements:FALLBACK[key]||[unit.element||'light'],family=data.sourceFamily||def?.family||key,type=data.sourceType||def?.id||unit.type,token=key+'|'+type,old=entries.get(token);if(old){old.stacks++;old.ttl=Math.max(old.ttl||0,data.ttl||0);return;}entries.set(token,{key,sourceType:type,sourceId:data.sourceId,sourceName:data.sourceName||def?.name||family,sourceFamily:family,elements,colors:[...new Set([elements.includes(STATUS_ELEMENT[key])?STATUS_ELEMENT[key]:data.sourceElement||def?.element||elements[0],...elements])].map(e=>COLORS[e]).filter(Boolean),tier:data.sourceTier||def?.tier||1,ttl:data.ttl??null,maxTTL:DURATIONS[key]||(key==='clone'?[10,20,80][(data.sourceTier||def?.tier||1)-1]:data.ttl)||1,amount:data.amount??null,stacks:data.stacks||1});};
 for(const [key,value] of Object.entries(unit.buffs||unit.status||{}))if(value.ttl>0)add(key,value);
 for(const dot of unit.dots||[])if(dot.ttl>0){const def=defs[dot.tower?.type],family=dot.sourceFamily||def?.family;add(family==='flame'?'burn':family||'burn',dot,def);}
 for(const mark of unit.napalm||[])add('napalm',mark,defs[mark.tower?.type]);
 const own=defs[unit.type];if(unit.cloneTTL>0)add('clone',{...unit.cloneSource,ttl:unit.cloneTTL},own);if(own?.family==='magic'&&unit.abilityCooldown>0)add('magic',{ttl:unit.abilityCooldown},own);if(own?.family==='zealot'&&unit.stack>0)add('zealot',{stacks:unit.stack},own);if(own?.family==='quark'&&unit.stack>0)add('quark',{},own);if(own?.family==='tidal'&&unit.charge>0)add('tidal',{},own);
 if(unit.shield>0)add('shield',{ttl:unit.shield,sourceFamily:'mechanical',sourceElements:[unit.element]});if(unit.resurrecting>0)add('revive',{ttl:unit.resurrecting,sourceFamily:'undead',sourceElements:['darkness']});if(unit.image&&unit.ttl>0)add('image',{ttl:unit.ttl,sourceFamily:'image',sourceElements:[unit.element]});if(unit.healVisual?.ttl>0)add('healing',unit.healVisual);
 return [...entries.values()];}
const circle=(c,x,y,r)=>{c.beginPath();c.arc(x,y,r,0,Math.PI*2);};
function glyph(c,key,r,time){c.lineWidth=r*.18;c.lineCap='round';c.lineJoin='round';if(['well','tidal','stun'].includes(key)){c.beginPath();c.moveTo(0,-r);c.quadraticCurveTo(r*1.4,r*.5,0,r);c.quadraticCurveTo(-r*1.4,r*.5,0,-r);c.fill();}
 else if(['smith','burn','napalm'].includes(key)){c.beginPath();c.moveTo(-r*.7,r);c.lineTo(-r*.8,0);c.lineTo(0,-r*1.3);c.lineTo(r*.7,0);c.lineTo(r*.55,r);c.closePath();c.fill();c.fillStyle='#ffebb7';c.fillRect(-r*.15,0,r*.3,r*.7);}
 else if(['roots','muck','corrosion','healing'].includes(key)){if(key==='healing'){c.fillRect(-r,-r*.3,r*2,r*.6);c.fillRect(-r*.3,-r,r*.6,r*2);}else{for(const side of [-1,1]){c.beginPath();c.ellipse(side*r*.45,0,r*.65,r*.3,side*.65,0,Math.PI*2);c.fill();}c.beginPath();c.moveTo(0,r);c.lineTo(0,-r);c.stroke();}}
 else if(['polar','nova'].includes(key)){for(let i=0;i<3;i++){const a=i*Math.PI/3;c.beginPath();c.moveTo(Math.cos(a)*r,Math.sin(a)*r);c.lineTo(-Math.cos(a)*r,-Math.sin(a)*r);c.stroke();}}
 else if(key==='storm'||key==='fast'||key==='zealot'){c.beginPath();c.moveTo(r*.1,-r);c.lineTo(-r*.7,r*.15);c.lineTo(r*.2,0);c.lineTo(-r*.1,r);c.lineTo(r*.7,-r*.2);c.closePath();c.fill();}
 else if(['voodoo','revive'].includes(key)){circle(c,0,-r*.15,r*.75);c.fill();c.fillRect(-r*.45,r*.2,r*.9,r*.65);c.fillStyle='#1b122a';c.fillRect(-r*.45,-r*.3,r*.3,r*.25);c.fillRect(r*.15,-r*.3,r*.3,r*.25);}
 else if(['clone','image'].includes(key)){c.strokeRect(-r,-r*.7,r*1.2,r*1.5);c.strokeRect(-r*.2,-r,r*1.2,r*1.5);}
 else if(key==='shield'||key==='enchant'||key==='weaponArmor'){c.beginPath();c.moveTo(-r,-r*.8);c.lineTo(r,-r*.8);c.lineTo(r*.7,r*.5);c.lineTo(0,r);c.lineTo(-r*.7,r*.5);c.closePath();c.stroke();if(key!=='shield'){c.beginPath();c.moveTo(-r*.6,r*.8);c.lineTo(r*.6,-r*.8);c.stroke();}}
 else {for(let i=0;i<4;i++){const a=i*Math.PI/2+time;c.beginPath();c.moveTo(0,0);c.lineTo(Math.cos(a)*r,Math.sin(a)*r);c.stroke();}circle(c,0,0,r*.5);c.stroke();}}
export function drawStatusEffects(c,statuses,x,y,size,scale,time,layer){if(!statuses.length)return;const s=scale,ground=y+size*.12,r=size*.38;c.save();
 if(layer==='under'){for(const [i,status] of statuses.slice(0,6).entries()){const colors=status.colors.length?status.colors:[COLORS.light],color=colors[0],key=status.key;c.strokeStyle=color;c.fillStyle=color;c.globalAlpha=.55;c.lineWidth=3*s;
 if(['roots','muck','corrosion'].includes(key)){for(let j=0;j<4;j++){const a=j*Math.PI/2+i,px=x+Math.cos(a)*r,py=ground+Math.sin(a)*r*.35;c.beginPath();c.moveTo(px,py);c.quadraticCurveTo(x+Math.sin(a+time)*r*.8,y-size*.3,x+Math.cos(a+1)*r*.55,y-size*.55);c.stroke();}c.globalAlpha=.15;c.beginPath();c.ellipse(x,ground,r,r*.4,0,0,Math.PI*2);c.fill();}
 else if(['polar','nova','shield'].includes(key)){c.beginPath();for(let j=0;j<=6;j++){const a=j*Math.PI/3,px=x+Math.cos(a)*r*1.2,py=y-size*.25+Math.sin(a)*size*.48;j?c.lineTo(px,py):c.moveTo(px,py);}c.stroke();}
 else {c.beginPath();c.ellipse(x,ground,r+i*2*s,r*.3,0,0,Math.PI*2);c.stroke();}
 for(let j=0;j<3;j++){const a=time*(key==='well'?2:-1.2)+j*Math.PI*2/3+i,px=x+Math.cos(a)*r,py=ground+Math.sin(a)*r*.3-(Math.sin(time*3+j)+1)*12*s;c.fillStyle=colors[j%colors.length];c.strokeStyle=c.fillStyle;c.globalAlpha=.65;c.save();c.translate(px,py);glyph(c,key,9*s,time);c.restore();}}
 }else{statuses.slice(0,3).forEach((status,i)=>{const colors=status.colors.length?status.colors:[COLORS.light],px=x+(i-(Math.min(3,statuses.length)-1)/2)*52*s,py=y-size*.93;c.globalAlpha=.95;c.fillStyle='#101c19e6';circle(c,px,py,22*s);c.fill();c.strokeStyle=colors.at(-1);c.lineWidth=2*s;c.stroke();c.save();c.translate(px,py);c.fillStyle=colors[0];c.strokeStyle=colors[0];glyph(c,status.key,14*s,time);c.restore();if(status.ttl!==null){c.globalAlpha=.7;c.strokeStyle=colors[0];c.lineWidth=2*s;c.beginPath();c.arc(px,py,24*s,-Math.PI/2,-Math.PI/2+Math.PI*2*Math.min(1,status.ttl/status.maxTTL));c.stroke();}});if(statuses.length>3){c.fillStyle='#edf1cf';c.font=`${22*s}px monospace`;c.textAlign='center';c.fillText('+'+(statuses.length-3),x+90*s,y-size*.88);}}
 c.restore();}
